'use strict';
function exportPlainBody(text){return String(text).replace(/\[\[image:([a-zA-Z0-9-]+)\]\]/g,(_,id)=>{const a=(data.assets||[]).find(a=>a.id===id);return '[图片：'+(a?.name||'图片已移除')+']'})}
function exportMetadata(post){return {date:new Date(post.created).toLocaleString('zh-CN'),archives:linkedGameIds(post).map(id=>game(id)?.name).filter(Boolean),characters:post.characters.map(id=>character(id)?.name).filter(Boolean),tags:post.tags||[],comments:[...(post.comments||[])].sort((a,b)=>Date.parse(a.created)-Date.parse(b.created))}}
function exportFilename(title){return (String(title||'观星塔-帖子').replace(/[<>:"/\\|?*\u0000-\u001f]/g,'_').replace(/[. ]+$/g,'').slice(0,75)||'观星塔-帖子')}
function downloadExport(content,type,name){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
function postExportHtml(posts,{comments=true,images=true}={}){const stamp=new Date().toLocaleString('zh-CN');const articles=posts.map(p=>{const m=exportMetadata(p);const body=String(p.body).split(/(\[\[image:[a-zA-Z0-9-]+\]\])/g).map(part=>{const match=part.match(/^\[\[image:([a-zA-Z0-9-]+)\]\]$/);if(!match)return esc(part);const a=(data.assets||[]).find(a=>a.id===match[1]);return images&&a&&imageOK(a.src)?`<img src="${esc(a.src)}" alt="${esc(a.name)}">`:esc('[图片：'+(a?.name||'图片已移除')+']')}).join('');return `<article><p class="meta">${esc(m.date)}${p.status==='draft'?' · 草稿':''}</p>${p.title?'<h2>'+esc(p.title)+'</h2>':''}<div class="prose">${body}</div>${images?p.images.filter(imageOK).map((src,i)=>`<figure><img src="${esc(src)}" alt="附件图片 ${i+1}"></figure>`).join(''):p.images.length?'<p class="meta">附件图片：'+p.images.length+' 张（本次未包含）</p>':''}<p class="meta">${[m.archives.length?'档案：'+m.archives.join('、'):'',m.characters.length?'角色：'+m.characters.join('、'):'',m.tags.length?'标签：'+m.tags.join('、'):''].filter(Boolean).map(esc).join('<br>')}</p>${comments&&m.comments.length?'<section class="comments"><h3>后来的想法 · '+m.comments.length+'</h3>'+m.comments.map(c=>'<div class="comment"><p class="meta">'+esc(new Date(c.created).toLocaleString('zh-CN'))+(c.updated?' · 已编辑':'')+'</p><div class="prose">'+esc(c.body)+'</div></div>').join('')+'</section>':''}</article>`}).join('');return '<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; img-src data:; style-src \'unsafe-inline\'"><title>'+esc(posts.length===1?posts[0].title||'观星塔手记':'观星塔-帖子存档')+'</title><style>body{max-width:820px;margin:45px auto;padding:0 24px;color:#302b25;background:#faf8f3;font:16px/1.9 system-ui,sans-serif}h1{font:30px Georgia,serif}h2{font-size:23px;line-height:1.5}.meta{font-size:12px;color:#665e52}article{border-top:1px solid #d4c9b8;padding:25px 0}.prose{white-space:pre-wrap;overflow-wrap:anywhere}img{display:block;max-width:100%;height:auto;max-height:800px;object-fit:contain;margin:16px auto}figure{margin:15px 0}.comments{border-left:2px solid #d4c9b8;padding-left:16px;margin-top:24px}h3{font-size:15px}.comment{margin:14px 0}footer{border-top:1px solid #d4c9b8;padding:15px 0;font-size:11px;color:#665e52}@media print{@page{margin:18mm}body{background:white;margin:0;max-width:none;padding:0;font-size:11pt}h1,h2,h3{break-after:avoid}img{max-height:230mm;break-inside:avoid}article{padding:15px 0}footer{font-size:9pt}}</style></head><body><h1>观星塔 · 帖子存档</h1><p class="meta">'+posts.length+' 篇 · 导出于 '+esc(stamp)+'</p>'+articles+'<footer>这是一份独立阅读副本。恢复观星塔档案请使用完整 JSON 备份。</footer></body></html>'}
function postExportText(posts,{comments=true}={}){return '观星塔 · 帖子存档\n'+posts.length+' 篇\n\n'+posts.map(p=>{const m=exportMetadata(p);return [p.title||'',m.date+(p.status==='draft'?' [草稿]':''),'',exportPlainBody(p.body),p.images.length?'\n[附件图片：'+p.images.length+' 张，TXT 不包含图片文件]':'','',m.archives.length?'档案：'+m.archives.join('、'):'',m.characters.length?'角色：'+m.characters.join('、'):'',m.tags.length?'标签：'+m.tags.join('、'):'',comments&&m.comments.length?'\n后来的想法\n'+m.comments.map(c=>new Date(c.created).toLocaleString('zh-CN')+'\n'+c.body).join('\n\n'):''].filter(x=>x!==undefined).join('\n')}).join('\n\n'+'─'.repeat(28)+'\n\n')}
function postExportCsv(posts,{comments=true}={}){const cell=value=>{let s=String(value??'');if(/^[\s]*[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};const rows=[['发帖时间','标题','正文','档案','角色','标签','状态','附件图片数','评论']];for(const p of posts){const m=exportMetadata(p);rows.push([m.date,p.title,exportPlainBody(p.body),m.archives.join('、'),m.characters.join('、'),m.tags.join('、'),p.status==='draft'?'草稿':'正式帖子',p.images.length,comments?m.comments.map(c=>new Date(c.created).toLocaleString('zh-CN')+' '+c.body).join('\n'):''])}return '\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n')}
function postExportMarkdown(posts,{comments=true,images=true}={}){const files=[],used=new Map(),markdownText=s=>String(s).replace(/[\\`*_{}\[\]<>#|]/g,'\\$&');function media(src){if(!imageOK(src))return null;if(used.has(src))return used.get(src);const match=src.match(/^data:image\/(jpeg|png|webp|gif);base64,([a-z0-9+/=\s]+)$/i);if(!match)return null;const path='images/image-'+String(files.length+1).padStart(4,'0')+'.'+(match[1].toLowerCase()==='jpeg'?'jpg':match[1].toLowerCase()),raw=atob(match[2].replace(/\s/g,'')),bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));files.push({name:path,bytes});used.set(src,path);return path}const md='# 观星塔 · 帖子存档\n\n'+posts.map(p=>{const m=exportMetadata(p);const body=p.body.replace(/\[\[image:([a-zA-Z0-9-]+)\]\]/g,(_,id)=>{const a=(data.assets||[]).find(a=>a.id===id),path=images&&a?media(a.src):null;return path?'\n\n!['+markdownText(a.name)+']('+path+')\n\n':'[图片：'+markdownText(a?.name||'图片已移除')+']'});const attachments=images?p.images.map((src,i)=>{const path=media(src);return path?'![附件图片 '+(i+1)+']('+path+')':''}).join('\n\n'):p.images.length?'[附件图片：'+p.images.length+' 张，本次未包含]':'';return [p.title?'## '+markdownText(p.title):'## 手记',m.date+(p.status==='draft'?' · 草稿':''),body,attachments,m.archives.length?'档案：'+markdownText(m.archives.join('、')):'',m.characters.length?'角色：'+markdownText(m.characters.join('、')):'',m.tags.length?'标签：'+markdownText(m.tags.join('、')):'',comments&&m.comments.length?'### 后来的想法\n\n'+m.comments.map(c=>new Date(c.created).toLocaleString('zh-CN')+'\n\n'+c.body).join('\n\n'):'' ].filter(Boolean).join('\n\n')}).join('\n\n---\n\n');const encoder=new TextEncoder();files.unshift({name:'观星塔-帖子.md',bytes:encoder.encode(md)});files.push({name:'阅读说明.txt',bytes:encoder.encode('解压后打开“观星塔-帖子.md”，请让 images 文件夹与它保持在同一目录。此包用于阅读；恢复网站内容请使用完整 JSON 备份。')});return files}
function exportZip(files){const encoder=new TextEncoder(),parts=[],central=[];let offset=0;function crc32(bytes){let c=0xffffffff;for(const byte of bytes){c^=byte;for(let i=0;i<8;i++)c=(c>>>1)^((c&1)?0xedb88320:0)}return (c^0xffffffff)>>>0}for(const f of files){const name=encoder.encode(f.name),bytes=f.bytes,crc=crc32(bytes),header=new Uint8Array(30+name.length),h=new DataView(header.buffer);h.setUint32(0,0x04034b50,true);h.setUint16(4,20,true);h.setUint16(6,0x800,true);h.setUint16(12,33,true);h.setUint32(14,crc,true);h.setUint32(18,bytes.length,true);h.setUint32(22,bytes.length,true);h.setUint16(26,name.length,true);header.set(name,30);parts.push(header,bytes);const entry=new Uint8Array(46+name.length),c=new DataView(entry.buffer);c.setUint32(0,0x02014b50,true);c.setUint16(4,20,true);c.setUint16(6,20,true);c.setUint16(8,0x800,true);c.setUint16(14,33,true);c.setUint32(16,crc,true);c.setUint32(20,bytes.length,true);c.setUint32(24,bytes.length,true);c.setUint16(28,name.length,true);c.setUint32(42,offset,true);entry.set(name,46);central.push(entry);offset+=header.length+bytes.length}const size=central.reduce((s,b)=>s+b.length,0),end=new Uint8Array(22),e=new DataView(end.buffer);e.setUint32(0,0x06054b50,true);e.setUint16(8,files.length,true);e.setUint16(10,files.length,true);e.setUint32(12,size,true);e.setUint32(16,offset,true);return new Blob([...parts,...central,end],{type:'application/zip'})}
function openPostExport(id){const single=id?data.posts.find(p=>p.id===id):null;if(id&&!single)return toast('这篇帖子已不存在。');const current=['graph','gallery','relations'].includes(view.type)?[]:visiblePosts();modal(`<form id="postExportForm"><h2>${single?'导出这篇帖子':'导出帖子'}</h2>${single?'<p class="hint">'+esc(single.title||'无标题手记')+'</p>':`<label class="field">导出范围<select id="postExportScope"><option value="current" ${current.length?'':'disabled'}>当前筛选结果（${current.length} 篇）</option><option value="published" ${current.length?'':'selected'}>全部正式帖子（${data.posts.filter(p=>p.status==='published').length} 篇）</option><option value="all">全部帖子，含草稿（${data.posts.length} 篇）</option></select></label>`}<label class="field">文件格式<select id="postExportFormat"><option value="html">HTML · 带图片，可离线打开</option><option value="markdown">Markdown + 图片 · ZIP 压缩包</option><option value="txt">TXT · 纯文字</option><option value="csv">CSV · 用表格查看</option><option value="pdf">PDF · 通过打印保存</option></select></label><div class="exportOptions"><label><input id="postExportComments" type="checkbox" checked> 包含评论</label><label><input id="postExportImages" type="checkbox" checked> 包含图片</label></div><p id="postExportHint" class="hint"></p><p class="hint">这些文件用于阅读、归档和分享。换浏览器恢复全部内容，请使用“导出全部备份”的 JSON 文件。</p><div class="dialogActions"><button type="button" data-action="close">取消</button><button class="primary" type="submit" id="postExportSubmit">导出文件</button></div></form>`);const format=$('postExportFormat'),hint=$('postExportHint');const hints={html:'图片嵌入同一个 HTML 文件，断网后也能在浏览器里阅读。',markdown:'ZIP 内包含 Markdown 文稿及 images 图片目录，解压后放在一起阅读。',txt:'仅导出文字和图片说明，不包含图片文件。',csv:'一篇帖子一行，包含日期、正文、关联信息和评论；不包含图片。',pdf:'将打开排版后的页面和打印窗口，请选择“另存为 PDF”。'};const sync=()=>{hint.textContent=hints[format.value];$('postExportImages').disabled=['txt','csv'].includes(format.value);$('postExportSubmit').textContent=format.value==='pdf'?'打开打印 / 保存 PDF':'导出文件'};format.onchange=sync;sync();$('postExportForm').onsubmit=async e=>{e.preventDefault();const scope=single?'single':$('postExportScope').value,posts=single?[single]:scope==='all'?data.posts:scope==='published'?data.posts.filter(p=>p.status==='published'):visiblePosts();if(!posts.length)return toast('这个范围内还没有帖子。');const options={comments:$('postExportComments').checked,images:$('postExportImages').checked&&!$('postExportImages').disabled},name=exportFilename(single?single.title||'观星塔手记':'观星塔-帖子-'+localDateKey(new Date())),type=format.value;try{if(type==='pdf'){const w=window.open('','_blank');if(!w)return toast('打印页面被浏览器拦截，请允许弹窗，或选择 HTML 导出。');w.opener=null;w.document.open();w.document.write(postExportHtml(posts,options));w.document.close();const loaded=[...w.document.images].map(img=>img.complete?Promise.resolve():new Promise(resolve=>{img.onload=resolve;img.onerror=resolve}));Promise.all(loaded).then(()=>setTimeout(()=>{if(!w.closed){w.focus();w.print()}},250));return}if(type==='markdown'){const zip=exportZip(postExportMarkdown(posts,options));downloadExport(zip,'application/zip',name+'.zip')}else if(type==='html')downloadExport(postExportHtml(posts,options),'text/html;charset=utf-8',name+'.html');else if(type==='txt')downloadExport('\ufeff'+postExportText(posts,options),'text/plain;charset=utf-8',name+'.txt');else downloadExport(postExportCsv(posts,options),'text/csv;charset=utf-8',name+'.csv');toast('已导出 '+posts.length+' 篇帖子。')}catch{toast('导出失败，请缩小范围或关闭图片后重试。')}}}
function storageHelp(){modal('<h2>把观星塔好好保存下来</h2><p>内容目前保存在<strong>当前设备、当前浏览器</strong>。换浏览器后看到空白，不代表原浏览器里的记录被删除，也不会自动同步。</p><ol class="storageSteps"><li>在原浏览器点击“导出全部备份”，保存 JSON 文件。</li><li>把备份留在电脑、移动硬盘或你自己的网盘中，定期保留不同日期的副本。</li><li>在新浏览器打开同一个观星塔网址，点击“导入备份”。导入会替换新浏览器当前的档案，请先备份。</li></ol><p class="hint">完整 JSON 备份包含帖子、评论、图片、头像、关系图与主题。HTML、Markdown、TXT、CSV、PDF 用于阅读，不是完整恢复文件。</p><p class="hint">目前没有账号或云端自动同步；清除网站数据仍可能删除本机记录。</p><div class="dialogActions"><button data-action="close">明白了</button><button id="backupNow" class="primary">下载完整备份</button></div>');$('backupNow').onclick=()=>$('export').click()}
const exportFeed=renderFeed;renderFeed=function(){exportFeed();document.querySelectorAll('.journalPost').forEach(card=>{const menu=card.querySelector('.postMoreMenu');if(menu&&!menu.querySelector('[data-export-post]')){const b=document.createElement('button');b.type='button';b.dataset.exportPost=card.dataset.postId;b.textContent='导出帖子';menu.append(b)}})};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.exportPost)openPostExport(b.dataset.exportPost);document.querySelectorAll('.postMore[open]').forEach(d=>{if(!d.contains(e.target))d.open=false})});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.postMore[open]').forEach(d=>{d.open=false;if(d.contains(e.target))d.querySelector('summary').focus()})});
window.addEventListener('DOMContentLoaded',()=>{const buttons=document.querySelector('footer>div');const exportPosts=document.createElement('button');exportPosts.type='button';exportPosts.id='exportPosts';exportPosts.textContent='导出帖子';exportPosts.onclick=()=>openPostExport();const help=document.createElement('button');help.type='button';help.id='storageHelp';help.textContent='保存与迁移';help.onclick=storageHelp;buttons.prepend(exportPosts,help)});
